create table if not exists public.operating_expenses(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,expense_date date not null default current_date,category text not null,description text,amount_subunits integer not null check(amount_subunits>=0),currency text not null default 'JOD',supplier_id uuid references public.suppliers(id) on delete set null,payment_status text not null default 'unpaid' check(payment_status in('unpaid','partially_paid','paid','cancelled')),amount_paid_subunits integer not null default 0 check(amount_paid_subunits>=0 and amount_paid_subunits<=amount_subunits),created_by uuid references public.clinic_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.supplier_obligations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete restrict,purchase_order_id uuid references public.purchase_orders(id) on delete set null,amount_subunits integer not null check(amount_subunits>=0),amount_paid_subunits integer not null default 0 check(amount_paid_subunits>=0 and amount_paid_subunits<=amount_subunits),due_date date,status text not null default 'open' check(status in('open','partially_paid','paid','cancelled')),created_by uuid references public.clinic_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.supplier_payments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,supplier_obligation_id uuid not null references public.supplier_obligations(id) on delete restrict,amount_subunits integer not null check(amount_subunits>0),paid_at timestamptz not null default now(),payment_method text,reference text,created_by uuid references public.clinic_users(id) on delete set null);
alter table public.workforce_commission_entries add column if not exists source_payment_id uuid references public.invoice_payments(id) on delete set null;
create index if not exists operating_expenses_tenant_date_idx on public.operating_expenses(tenant_id,expense_date); create index if not exists supplier_obligations_tenant_supplier_idx on public.supplier_obligations(tenant_id,supplier_id,status); create index if not exists supplier_payments_obligation_idx on public.supplier_payments(tenant_id,supplier_obligation_id);
alter table public.operating_expenses enable row level security; alter table public.supplier_obligations enable row level security; alter table public.supplier_payments enable row level security;
create policy operating_expenses_access on public.operating_expenses for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'expenses:manage')) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'expenses:manage'));
create policy supplier_obligations_access on public.supplier_obligations for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'purchasing:manage')) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'purchasing:manage'));
create policy supplier_payments_access on public.supplier_payments for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'purchasing:manage')) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'purchasing:manage'));
insert into public.permissions(permission_key,permission_name,description,resource,action) values('expenses:manage','Manage Operating Expenses','Record and manage operating expenses','expenses','manage') on conflict(permission_key) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.role_key in('clinic_admin','accounting') and p.permission_key='expenses:manage' on conflict do nothing;
grant select,insert,update,delete on public.operating_expenses,public.supplier_obligations,public.supplier_payments to authenticated; grant all on public.operating_expenses,public.supplier_obligations,public.supplier_payments to service_role;